def norm(S):
    mr=min(r for r,c in S); mc=min(c for r,c in S)
    return frozenset((r-mr,c-mc) for r,c in S)
def d4_normal_forms(S):
    # transform unbounded coords around origin
    forms=[]
    for t in range(8):
        out=set()
        for r,c in S:
            ops=[(r,c),(c,-r),(-r,-c),(-c,r),(r,-c),(-r,c),(c,r),(-c,-r)]
            out.add(ops[t])
        forms.append(norm(out))
    return forms

def find_instances(points, pattern):
    forms=set(d4_normal_forms(pattern))
    found=[]
    for form in forms:
        h=max(r for r,c in form)+1; w=max(c for r,c in form)+1
        for dr in range(15-h+1):
            for dc in range(15-w+1):
                coords={(r+dr,c+dc) for r,c in form}
                if coords<=points:
                    found.append((dr,dc,form,coords))
    return found
print('output shape instances input?',find_instances(A3demo,C3demo))

def comps(points, diag=True):
    pts=set(points); out=[]
    while pts:
        seed=pts.pop(); comp={seed}; todo=[seed]
        while todo:
            r,c=todo.pop()
            for dr in (-1,0,1):
             for dc in (-1,0,1):
              if not diag and abs(dr)+abs(dc)!=1: continue
              q=(r+dr,c+dc)
              if q in pts:
               pts.remove(q); comp.add(q); todo.append(q)
        out.append(comp)
    return sorted(out,key=lambda x:(-len(x),min(x)))
