def find_instances_n(points, pattern, n=12):
    forms=set(d4_normal_forms(pattern)); found=[]
    for form in forms:
        h=max(r for r,c in form)+1; w=max(c for r,c in form)+1
        for dr in range(n-h+1):
            for dc in range(n-w+1):
                coords={(r+dr,c+dc) for r,c in form}
                if coords<=points:
                    found.append((dr,dc,form,coords))
    return found
